(1, 'seafdec', '822e8a75145ea014267b1cf99b4b85f57dcd8d4712737afbc453d2079f6cc478', 'https://repository.seafdec.org.ph/handle/10862/1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skipped', 'No supported scholarly citation metadata was found.', NULL, '2026-08-31 04:05:23', NULL, '2026-09-30 04:05:29', '2026-08-31 04:05:23', '2026-08-31 04:05:29'),
(2, 'seafdec', '199a4422766eb6439f64636840983cbc966237278e80330d22aefde1d707516f', 'https://repository.seafdec.org.ph/handle/10862/1660', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skipped', 'No supported scholarly citation metadata was found.', NULL, '2026-08-31 04:05:29', NULL, '2026-09-30 04:05:36', '2026-08-31 04:05:23', '2026-08-31 04:05:36'),
(3, 'seafdec', '0617796aad40a575331f3ada94b017d14a6560199fc3ac4bd6dab687c1761ed0', 'https://repository.seafdec.org.ph/handle/10862/3572', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'failed', 'The repository could not be reached or is already being harvested.', NULL, '2026-08-31 04:05:36', NULL, '2026-09-01 04:05:45', '2026-08-31 04:05:23', '2026-08-31 04:05:45'),
(4, 'seafdec', '4fb131a8854a2c5a1b20402a0c59427408ca4e55e34a651a8caa292976e7b281', 'https://repository.seafdec.org.ph/handle/10862/3152', '467f4ad79f6c710d342c7e873a6c6c649307521f1f0ef2766026d34f10e0c61b', 'Library and databanking services of SEAFDEC/AQD', 'Pacino, Luisa G.', 'The Library of SEAFDEC Aquaculture Department (AQD) serves the information needs of scientists & researchers; AQD staff, trainees & interns; fish farmers; students; and other visitors. It is organized according to the Library of Congress Classification Scheme, and its collection is accessible through the internet via the Online Public Access Catalogue portal on the AQD website (www.seafdec.org.ph). Established in 1976, AQD Library is now reputed to have the best collection on aquaculture in Southeast Asia and has become a popular aquaculture reference resource for academic and research institutions in the Philippines and abroad. It is important for AQD to have a cutting-edge library collection to enable its scientists and researchers to access the best and current scientific literature. In 2007, AQD Library expanded its collection by networking with the International Association of Aquatic and Marine Science Libraries and Information Centers (IAMSLIC, www.iamslic.org). The Library has also existing gifts/exchanges agreements with the libraries of FAO, UPV, WorldFish Centre, and several institutions in SEAFDEC member countries. It is a member of the Philippine Association of Academic and Research Libraries (PAARL), the Philippine Librarians Association Inc. (PLAI), and the Association of Special Libraries of the Philippines (ASLP).', 2009, NULL, '{\"type\": \"Book chapter\", \"venue\": \"Training Handbook on Rural Aquaculture\", \"method\": \"html_metadata\", \"license\": null, \"language\": \"en\", \"publisher\": \"Aquaculture Department, Southeast Asian Fisheries Development Center\"}', 'ready', NULL, NULL, '2026-08-31 04:22:44', '2026-08-31 04:22:46', '2026-09-30 04:22:46', '2026-08-31 04:17:44', '2026-08-31 04:22:46');

