(34, 6, 'detailed_proposal', 0, '{\"staff\": null, \"rationale\": \"<br><p></p>\", \"references\": \"<p></p><p>[1] E. EE., &quot;Eliminating Setup Friction in PHP Web Development Labs Using Docker and DevContainers,&quot; 2026. doi: 10.21203/rs.3.rs-10356699/v1. [Online]. Available: https://europepmc.org/article/PPR/PPR1300102.</p>\", \"methodology\": {\"data_analysis\": \"\", \"research_design\": \"\", \"specific_methods\": \"\"}, \"introduction\": \"\", \"leader_email\": \"23-78498@g.batstate-u.edu.ph\", \"leader_title\": null, \"leader_contact\": \"09238420348\", \"executive_brief\": \"<br>\", \"research_agenda\": null, \"approved_by_name\": null, \"expected_outputs\": {\"patent\": [], \"policy\": [], \"product\": [], \"publication\": [], \"social_impact\": [], \"people_service\": [], \"economic_impact\": [], \"place_partnership\": []}, \"proponent_campus\": \"BatStateU The NEU ARASOF-Nasugbu Campus\", \"responsibilities\": [{\"name\": \"\", \"duties\": \"\", \"percentage\": \"100\"}], \"general_objective\": \"\", \"proponent_college\": \"College of Informatics and Computing Sciences\", \"cooperating_agency\": null, \"methodology_images\": [], \"related_literature\": \"To address the challenges students face when configuring local development environments, a multi-semester case study across two universities in Bahrain evaluated the transition from traditional XAMPP setups to containerized environments using Docker and DevContainers. The traditional approach introduced various friction points, such as operating system inconsistencies, configuration errors, and database credential mismatches, which often jeopardized laboratory progress. By implementing containerization, the setup time for the PHP web development labs was reduced by over ninety percent, decreasing from more than two hours to under ten minutes. This transition successfully minimized configuration barriers regardless of whether it was deployed at the start or mid-semester. Grounded in cognitive load theory, the findings suggest that container-based environments not only improve time efficiency but also mitigate extraneous cognitive load by eliminating single points of failure. Consequently, students completed their laboratory sessions more independently and in a timely manner, showcasing the educational utility of containerized workflows.<span data-proposal-citation=\\\"4\\\"> [1]</span><p><span data-proposal-citation=\\\"4\\\"> [1]</span></p>\", \"specific_objectives\": [], \"literature_citations\": \"[{\\\"id\\\":\\\"4638a9ba-e770-4bcd-ad2b-71a2c0f09c25\\\",\\\"source_link_id\\\":4,\\\"literature_source_id\\\":4,\\\"field\\\":\\\"related_literature\\\",\\\"selected_text\\\":\\\"To address the challenges students face when configuring local development environments, a multi-semester case study across two universities in Bahrain evaluated the transition from traditional XAMPP setups to containerized environments using Docker and DevContainers. The traditional approach introduced various friction points, such as operating system inconsistencies, configuration errors, and database credential mismatches, which often jeopardized laboratory progress. By implementing containerization, the setup time for the PHP web development labs was reduced by over ninety percent, decreasing from more than two hours to under ten minutes. This transition successfully minimized configuration barriers regardless of whether it was deployed at the start or mid-semester. Grounded in cognitive load theory, the findings suggest that container-based environments not only improve time efficiency but also mitigate extraneous cognitive load by eliminating single points of failure. Consequently, students completed their laboratory sessions more independently and in a timely manner, showcasing the educational utility of containerized workflows.\\\",\\\"locator\\\":\\\"\\\",\\\"created_at\\\":\\\"2026-09-03T02:22:47.640Z\\\"},{\\\"id\\\":\\\"d5d38335-65e5-45a2-aad2-29cc44b85b94\\\",\\\"source_link_id\\\":5,\\\"literature_source_id\\\":5,\\\"field\\\":\\\"related_literature\\\",\\\"selected_text\\\":\\\"the study provides an overview of utilizing the Django Python framework to construct research-oriented web applications, specifically targeting behavioral scientists with basic coding experience. The author outlines the fundamental architecture of web applications, detailing essential Django components such as URL routing, views, templates, and database models. To demonstrate practical utility, the work highlights several custom-built platforms, including TestXR for immersive virtual and augmented reality research, LiveQual for qualitative data collection via WhatsApp, and InclusivityXR for automated computer-vision-based accessibility auditing. Additionally, the paper discusses common development pitfalls, deployment considerations, and useful packages within the Django ecosystem. By bridging technical web development concepts with behavioral research needs, this guide aims to equip researchers with the foundational knowledge required to develop, structure, and deploy their own specialized web applications for data collection and experimental research.\\\",\\\"locator\\\":\\\"\\\",\\\"created_at\\\":\\\"2026-09-03T02:23:45.856Z\\\"}]\", \"proponent_department\": \"\", \"checked_verified_by_name\": null, \"recommending_approval_name\": null, \"specific_method_objectives\": [{\"heading\": \"\", \"methods\": []}], \"literature_research_history\": \"[{\\\"id\\\":\\\"web development-1788402150160\\\",\\\"query\\\":\\\"web development\\\",\\\"label\\\":\\\"web development\\\",\\\"context\\\":[\\\"Project title\\\"],\\\"resultCount\\\":0,\\\"searchedAt\\\":\\\"\\\"}]\"}', NULL, NULL, NULL, NULL, NULL, NULL, 12, '2026-09-03 02:00:08', '2026-09-24 04:39:24'),
(35, 7, 'detailed_proposal', 0, '{\"sdgs\": [\"1\", \"5\"], \"staff\": null, \"rationale\": \"sample<p></p>\", \"references\": \"<p></p><p>[1] M. Grinberg, &quot;Flask Web Development: Developing Web Applications with Python,&quot; 2014. [Online]. Available: http://deposit.dnb.de/cgi-bin/dokserv?id=4625553&amp;prov=M&amp;dok_var=1&amp;dok_ext=htm.</p>\", \"methodology\": {\"data_analysis\": \"\", \"research_design\": \"sample<p></p>\", \"specific_methods\": \"<p><strong>A. sample</strong></p><ol><li>sample</li></ol>\"}, \"introduction\": \"sample<p></p>\", \"leader_email\": \"23-73453@g.batstate-u.edu.ph\", \"leader_title\": null, \"leader_contact\": \"\", \"executive_brief\": \"sample<p></p>\", \"research_agenda\": \"sample\", \"approved_by_name\": \"SAMPLE\", \"expected_outputs\": {\"patent\": [{\"unit\": \"\", \"quantity\": null, \"description\": \"sample\"}], \"policy\": [{\"unit\": \"\", \"quantity\": null, \"description\": \"sample\"}], \"product\": [{\"unit\": \"\", \"quantity\": null, \"description\": \"sample\"}], \"publication\": [{\"unit\": \"\", \"quantity\": null, \"description\": \"sample\"}], \"social_impact\": [{\"unit\": \"\", \"quantity\": null, \"description\": \"sample\"}], \"people_service\": [{\"unit\": \"\", \"quantity\": null, \"description\": \"sample\"}], \"economic_impact\": [{\"unit\": \"\", \"quantity\": null, \"description\": \"sample\"}], \"place_partnership\": [{\"unit\": \"\", \"quantity\": null, \"description\": \"sample\"}]}, \"proponent_campus\": \"BatStateU The NEU ARASOF-Nasugbu Campus\", \"responsibilities\": [{\"name\": \"Djanisse Villaflor\", \"duties\": \"\", \"percentage\": \"100\"}], \"general_objective\": \"sample<p></p>\", \"proponent_college\": \"\", \"cooperating_agency\": null, \"methodology_images\": [{\"id\": \"b885bf12-74ad-4e69-be0c-92aa24a44cfc\", \"path\": \"proposal-drafts/2/7/detailed-proposal/methodology-images/1kDVx94NTk5aw23KvchiJYhbDaG5i3ubs7XmrZyR.png\", \"size\": \"medium\", \"caption\": \"\", \"section\": \"research_design\", \"alignment\": \"center\", \"mime_type\": \"image/png\", \"original_filename\": \"Gemini_Generated_Image_agtgymagtgymagtg.png\"}], \"related_literature\": \"Flask serves as a highly flexible Python-based microframework that grants developers significant creative control by avoiding the rigid development guidelines imposed by alternative frameworks. Through a structured development process, the framework&#039;s core functionalities can be leveraged to build and scale web applications. Key components of this ecosystem include templates, database integration, web forms, and email support. Furthermore, Flask facilitates the organization of large-scale applications through modular packages, allowing for the seamless implementation of user authentication, roles, and profile management. To extend application utility, the framework supports the creation of RESTful APIs that expose features to external clients, such as mobile devices and third-party systems. Finally, the development workflow is supported by robust unit testing, performance optimization strategies, and diverse production deployment options, illustrating Flask&#039;s capability to manage the entire application lifecycle while preserving developer autonomy.<span data-proposal-citation=\\\"6\\\"> [1]</span>\", \"specific_objectives\": [], \"literature_citations\": \"[{\\\"id\\\":\\\"b10c931d-59a1-4cc1-a804-680d56306b76\\\",\\\"source_link_id\\\":6,\\\"literature_source_id\\\":6,\\\"field\\\":\\\"related_literature\\\",\\\"selected_text\\\":\\\"Flask serves as a highly flexible Python-based microframework that grants developers significant creative control by avoiding the rigid development guidelines imposed by alternative frameworks. Through a structured development process, the framework\'s core functionalities can be leveraged to build and scale web applications. Key components of this ecosystem include templates, database integration, web forms, and email support. Furthermore, Flask facilitates the organization of large-scale applications through modular packages, allowing for the seamless implementation of user authentication, roles, and profile management. To extend application utility, the framework supports the creation of RESTful APIs that expose features to external clients, such as mobile devices and third-party systems. Finally, the development workflow is supported by robust unit testing, performance optimization strategies, and diverse production deployment options, illustrating Flask\'s capability to manage the entire application lifecycle while preserving developer autonomy.\\\",\\\"locator\\\":\\\"\\\",\\\"created_at\\\":\\\"2026-09-03T08:46:17.011Z\\\"}]\", \"proponent_department\": \"\", \"checked_verified_by_name\": \"SAMPLE\", \"recommending_approval_name\": \"SAMPLE\", \"specific_method_objectives\": [{\"heading\": \"sample\", \"methods\": [{\"description\": \"sample\"}]}], \"literature_research_history\": \"[{\\\"id\\\":\\\"web development-1788425105399\\\",\\\"query\\\":\\\"web development\\\",\\\"label\\\":\\\"web development\\\",\\\"context\\\":[\\\"Project title\\\",\\\"General objective\\\"],\\\"resultCount\\\":50,\\\"searchedAt\\\":\\\"2026-09-03T08:45:05.399Z\\\"}]\"}', NULL, NULL, NULL, NULL, NULL, NULL, 24, '2026-09-03 08:43:12', '2026-09-03 08:47:18'),
(36, 8, 'detailed_proposal', 0, '{\"sdgs\": [\"3\", \"4\", \"7\"], \"staff\": null, \"rationale\": \"<p>Many students manage schoolwork, deadlines, and personal responsibilities without a convenient way to reflect on their emotional state or notice patterns over time. Recording moods and habits in scattered tools or paper notes can be inconsistent and difficult to review. A dedicated mobile application can centralize self-monitoring, surface helpful trends, and connect students to available support resources, supporting earlier awareness and better well-being outcomes.</p>\", \"references\": \"<p>[1] J. Doe, Mobile Health Applications and Student Well-being. Metro Manila: University Press, 2021.<br>\\n[2] A. Smith, &quot;Designing mood-tracking apps,&quot; Journal of Digital Health, vol. 12, no. 3, pp. 45-58, 2022.</p>\", \"methodology\": {\"data_analysis\": \"<p>Functional test results will be summarized by passed and failed scenarios. Usability observations and student feedback will be grouped by recurring issue, task clarity, and improvement priority for the next iteration.</p>\", \"research_design\": \"<p>The project will use a developmental research design with an iterative design-build-evaluate approach. Requirements will be translated into a working mobile prototype, reviewed through representative use scenarios, and refined based on documented findings and user feedback.</p>\", \"specific_methods\": \"<p><strong>A. Requirements and design</strong></p><ol><li>Review available wellness-tracking practices and interview a sample of students about their needs and preferences.</li><li>Define the mood, habit, and support-resource features together with privacy and notification rules.</li><li>Prepare the interface and data model for review.</li></ol><p><strong>B. Development and integration</strong></p><ol><li>Implement the daily check-in, habit tracking, trend summary, and resource directory modules.</li><li>Connect modules and apply account security, data privacy, and guided onboarding flows.</li><li>Prepare representative student data and scenarios for functional testing.</li></ol><p><strong>C. Testing and evaluation</strong></p><ol><li>Run functional tests for check-ins, habit updates, trend viewing, and resource access.</li><li>Observe representative students completing selected tasks and record usability findings.</li><li>Prioritize corrections and document recommended improvements.</li></ol>\"}, \"introduction\": \"<p>Mental and emotional well-being is essential to a productive student life. Students who can recognize their feelings, track daily habits, and identify personal patterns are better positioned to manage stress and seek support early. This project presents the development of a Student Mental Health and Wellness Tracking Mobile App that provides a private and structured way for students to record moods, monitor wellness habits, and discover appropriate resources.</p>\", \"leader_email\": \"23-73453@g.batstate-u.edu.ph\", \"leader_title\": null, \"leader_contact\": \"09171234567\", \"executive_brief\": \"<p>The Student Mental Health and Wellness Tracking Mobile App will provide students with a private, easy-to-use tool for logging their mood, tracking wellness habits, and viewing guided self-care resources. The project combines structured daily check-ins, visual trend summaries, and referral prompts so that students can become more aware of their emotional well-being and seek appropriate support when needed.</p>\", \"research_agenda\": \"Good Health and Well-being, Digital Transformation, and Inclusive Education\", \"approved_by_name\": null, \"expected_outputs\": {\"patent\": [], \"policy\": [], \"product\": [{\"unit\": \"\", \"quantity\": null, \"description\": \"One (1) functional mobile application prototype for mood logging, wellness tracking, and support-resource access.\"}], \"publication\": [], \"social_impact\": [{\"unit\": \"\", \"quantity\": null, \"description\": \"One (1) usability assessment of the mobile application based on representative student feedback.\"}], \"people_service\": [{\"unit\": \"\", \"quantity\": null, \"description\": \"One (1) user guide and orientation material for students and guidance personnel.\"}], \"economic_impact\": [], \"place_partnership\": []}, \"proponent_campus\": \"BatStateU The NEU ARASOF-Nasugbu Campus\", \"responsibilities\": [{\"name\": \"Djanisse Villaflor\", \"duties\": \"<p>Lead the requirements analysis, design, development, testing, documentation, and preparation of the project outputs.</p>\", \"percentage\": \"100\"}], \"general_objective\": \"<p>To design and develop a Student Mental Health and Wellness Tracking Mobile App that enables students to record daily moods and wellness habits, review personal trends, and access appropriate support resources.</p>\", \"proponent_college\": \"College of Informatics and Computing Sciences\", \"cooperating_agency\": null, \"methodology_images\": [], \"related_literature\": \"<p>Research on mobile health applications emphasizes user engagement, privacy, and simple interaction design as key to sustained self-monitoring. Studies show that structured mood tracking and habit logging can improve self-awareness and encourage help-seeking behavior. These principles guide the proposed application by shaping its daily check-in flow, trend summaries, and referral pathways while tailoring the implementation to the needs of students.</p>\", \"specific_objectives\": [{\"description\": \"Identify the functional requirements for mood logging, wellness tracking, progress summaries, and support-resource access.\"}, {\"description\": \"Design a clear user interface and data model for daily check-ins, habit tracking, and trend visualization.\"}, {\"description\": \"Develop and integrate the mobile application modules with privacy safeguards, notifications, and accessible navigation.\"}, {\"description\": \"Evaluate the application through usability testing with representative students and document recommended improvements.\"}], \"literature_citations\": \"[]\", \"proponent_department\": \"\", \"checked_verified_by_name\": null, \"recommending_approval_name\": null, \"specific_method_objectives\": [{\"heading\": \"Requirements and design\", \"methods\": [{\"description\": \"Review available wellness-tracking practices and interview a sample of students about their needs and preferences.\"}, {\"description\": \"Define the mood, habit, and support-resource features together with privacy and notification rules.\"}, {\"description\": \"Prepare the interface and data model for review.\"}]}, {\"heading\": \"Development and integration\", \"methods\": [{\"description\": \"Implement the daily check-in, habit tracking, trend summary, and resource directory modules.\"}, {\"description\": \"Connect modules and apply account security, data privacy, and guided onboarding flows.\"}, {\"description\": \"Prepare representative student data and scenarios for functional testing.\"}]}, {\"heading\": \"Testing and evaluation\", \"methods\": [{\"description\": \"Run functional tests for check-ins, habit updates, trend viewing, and resource access.\"}, {\"description\": \"Observe representative students completing selected tasks and record usability findings.\"}, {\"description\": \"Prioritize corrections and document recommended improvements.\"}]}], \"literature_research_history\": \"[]\"}', NULL, NULL, NULL, NULL, NULL, '2026-09-03 09:02:21', 3, '2026-09-03 09:02:21', '2026-09-26 01:04:56'),
(37, 8, 'work_plan', 0, '{\"entries\": [{\"months\": [1, 2, 3], \"activity\": \"Interview a sample of students, review wellness-tracking practices, and document the mood, habit, and support-resource features.\", \"objective\": \"Analyze student wellness needs and define the requirements for the mobile tracking application.\", \"expected_output\": \"Validated requirements specification and interface design.\"}, {\"months\": [4, 5, 6, 7, 8], \"activity\": \"Implement the daily check-in, habit tracking, trend summary, and resource directory modules, then apply security, privacy, and onboarding flows.\", \"objective\": \"Develop and integrate the mobile application modules with privacy safeguards.\", \"expected_output\": \"Working application prototype with check-in, habit, trend, and resource modules.\"}, {\"months\": [9, 10, 11, 12], \"activity\": \"Run functional tests for check-ins, habit updates, trend viewing, and resource access; observe representative students and record usability findings.\", \"objective\": \"Test the application functions and usability, then document recommended improvements.\", \"expected_output\": \"Functional and usability test results with a list of prioritized improvements.\"}], \"planned_end\": \"2027-08-31\", \"prepared_by\": \"Djanisse Villaflor\", \"planned_start\": \"2026-09-01\", \"project_title\": \"Student Mental Health and Wellness Tracking Mobile App\", \"total_duration_months\": 12}', NULL, NULL, NULL, NULL, NULL, '2026-09-03 09:02:21', 2, '2026-09-03 09:02:21', '2026-09-26 01:04:56'),
