(40, 8, 'curriculum_vitae', 0, '{\"people\": [{\"email\": \"23-73453@g.batstate-u.edu.ph\", \"agency\": \"BatStateU The NEU ARASOF-Nasugbu Campus\", \"awards\": [], \"gender\": \"female\", \"street\": \"Sample Street\", \"barangay\": \"Sample Barangay\", \"birthday\": \"1998-07-22\", \"landline\": \"\", \"projects\": [{\"title\": \"Student Mental Health and Wellness Tracking Mobile App\", \"sector\": \"Socio-economics\", \"year_to\": \"2027\", \"year_from\": \"2026\", \"designation\": \"Project Leader\", \"current_status\": \"Proposed\"}], \"province\": \"Batangas\", \"cellphone\": \"09171234567\", \"last_name\": \"Villaflor\", \"employment\": [{\"agency\": \"BatStateU The NEU ARASOF-Nasugbu Campus\", \"end_date\": \"\", \"start_date\": \"2022-08-01\", \"monthly_salary\": 32000, \"appointment_status\": \"Contractual\", \"plantilla_position\": \"Faculty\"}], \"first_name\": \"Djanisse\", \"middle_name\": \"\", \"municipality\": \"Nasugbu\", \"publications\": [], \"scholarships\": [], \"presentations\": [], \"specializations\": [{\"field\": \"Mobile Application Development\", \"primary_field\": \"yes\"}], \"academic_background\": [{\"degree\": \"BS Information Technology\", \"sector\": \"ICT\", \"status\": \"Graduated\", \"thesis\": \"\", \"year_end\": \"2021\", \"year_start\": \"2017\", \"major_field\": \"Web and Mobile Development\", \"learning_institution\": \"Batangas State University\"}]}]}', NULL, NULL, NULL, NULL, NULL, '2026-09-03 09:02:21', 2, '2026-09-03 09:02:21', '2026-09-26 01:04:56'),
(202, 32, 'detailed_proposal', 0, '{\"sdgs\": [2, 13, 9], \"staff\": [], \"rationale\": \"Current practice in agricultural analytics still depends on manual processes and fragmented records. This leads to slow turnaround, limited visibility, and inconsistent reporting. A structured and technology-enabled approach can shorten processing time, strengthen traceability, and make outcomes easier to measure while keeping stakeholders in control of decisions.\", \"references\": \"Villamor, C. (2024). Machine learning for tropical crop yield estimation. Agriculture and Natural Resources, 18(3), 55-70. Santos, M. (2025). Applied research methods for community-centered technology. Philippine Journal of Science, 154(2), 101-115.\", \"methodology\": {\"data_analysis\": \"Quantitative results will be summarized using descriptive statistics, while qualitative feedback will undergo thematic analysis.\", \"research_design\": \"The study will use a developmental research design with mixed-method evaluation.\", \"specific_methods\": \"Researchers will review existing workflows, co-design the solution with stakeholders, implement it iteratively, and evaluate it through controlled pilot testing.\"}, \"introduction\": \"The project Machine Learning Approach to Rice Yield Prediction Using Weather and Soil Data responds to persistent gaps in agricultural analytics, where fragmented processes limit reliability and responsiveness. This study designs and evaluates a practical solution grounded in the day-to-day needs of its intended users.\", \"leader_email\": \"23-78498@g.batstate-u.edu.ph\", \"leader_title\": \"Mr.\", \"project_title\": \"Machine Learning Approach to Rice Yield Prediction Using Weather and Soil Data\", \"leader_contact\": \"09170000002\", \"project_leader\": \"Neil Carlo Delmo\", \"executive_brief\": \"This project will design, build, and evaluate a rice yield prediction model with a farmer-friendly advisory interface to improve how agricultural analytics is carried out in partner communities and campus units.\", \"research_agenda\": \"Agriculture, Food Security, and Climate Resilience\", \"approved_by_name\": \"Dr. Patricia Anne Villanueva\", \"expected_outputs\": {\"patent\": [], \"policy\": [{\"description\": \"An adoption guide for university and community stakeholders\"}], \"product\": [{\"description\": \"A rice yield prediction model with a farmer-friendly advisory interface\"}], \"publication\": [{\"description\": \"One peer-reviewed research article\"}], \"social_impact\": [{\"description\": \"Improved access to timely and reliable services for the target community\"}], \"people_service\": [{\"description\": \"A validated usability and acceptance report from pilot participants\"}], \"economic_impact\": [{\"description\": \"More efficient use of institutional and community resources\"}], \"place_partnership\": [{\"description\": \"A working partnership between the university and participating community sites\"}]}, \"proponent_campus\": \"Alangilan Campus\", \"responsibilities\": [{\"name\": \"Neil Carlo Delmo\", \"duties\": \"Leads project planning, implementation, quality assurance, data analysis, and reporting.\", \"percentage\": 100}], \"general_objective\": \"Develop and evaluate a rice yield prediction model with a farmer-friendly advisory interface.\", \"proponent_college\": \"College of Informatics and Computing Sciences\", \"_revision_sections\": {\"regions\": [{\"x\": 0.07401960659650417, \"y\": 0.11314105172442576, \"id\": \"section-project-information\", \"label\": \"I. Research Project Title\", \"width\": 0.8518791261062123, \"height\": 0.028846153846153848, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.1419872055705796, \"id\": \"section-research-agenda\", \"label\": \"II. Research Agenda\", \"width\": 0.8518791261062123, \"height\": 0.02425208458533654, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.16623929015591613, \"id\": \"section-sdgs\", \"label\": \"III. Sustainable Development Goal\", \"width\": 0.8518791261062123, \"height\": 0.16837610750116855, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.33461539765708465, \"id\": \"section-project-team\", \"label\": \"IV. Project Leader and Staff\", \"width\": 0.8518791261062123, \"height\": 0.09391021728515624, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.4285256149422409, \"id\": \"section-proponent\", \"label\": \"V. Proponent Agency\", \"width\": 0.8518791261062123, \"height\": 0.0623931884765625, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.4909188034188034, \"id\": \"section-cooperating-agency\", \"label\": \"VI. Cooperating Agency\", \"width\": 0.8518791261062123, \"height\": 0.023183773725460734, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.5141025771442641, \"id\": \"section-executive-brief\", \"label\": \"VII. Executive Brief\", \"width\": 0.8518791261062123, \"height\": 0.04946579892411191, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.5635683760683761, \"id\": \"section-rationale\", \"label\": \"VIII. Rationale\", \"width\": 0.8518791261062123, \"height\": 0.07767095321264023, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.6412393292810163, \"id\": \"section-objectives\", \"label\": \"IX. Objectives of the Project\", \"width\": 0.8518791261062123, \"height\": 0.15085468129215077, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.7920940105731671, \"id\": \"section-expected-outputs\", \"label\": \"X. Expected Output of the Project\", \"width\": 0.8518791261062123, \"height\": 0.1278846202752529, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.91997863084842, \"id\": \"section-literature\", \"label\": \"XI. Introduction and Related Literature\", \"width\": 0.8518791261062123, \"height\": 0.05686963888315057, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.04428178836137821, \"id\": \"section-literature\", \"label\": \"XI. Introduction and Related Literature\", \"width\": 0.8518791261062123, \"height\": 0.12676519410223022, \"pageNumber\": 2}, {\"x\": 0.07401960659650417, \"y\": 0.17104698246360844, \"id\": \"section-methodology\", \"label\": \"XII. Methodology\", \"width\": 0.8518791261062123, \"height\": 0.14722227438902244, \"pageNumber\": 2}, {\"x\": 0.07401960659650417, \"y\": 0.31826925685263086, \"id\": \"section-responsibilities\", \"label\": \"XIII. Duties and Responsibilities\", \"width\": 0.8518791261062123, \"height\": 0.06217943501268697, \"pageNumber\": 2}, {\"x\": 0.07401960659650417, \"y\": 0.3804486918653178, \"id\": \"section-work-plan\", \"label\": \"XIV. Major Activities / Work Plan\", \"width\": 0.8518791261062123, \"height\": 0.023183773725460734, \"pageNumber\": 2}, {\"x\": 0.07401960659650417, \"y\": 0.4036324655907786, \"id\": \"section-budget\", \"label\": \"XV. Line-Item Budget\", \"width\": 0.8518791261062123, \"height\": 0.06816000653128336, \"pageNumber\": 2}, {\"x\": 0.07401960659650417, \"y\": 0.47179247212206193, \"id\": \"section-references\", \"label\": \"XVI. References\", \"width\": 0.8518791261062123, \"height\": 0.06777896718082273, \"pageNumber\": 2}, {\"x\": 0.07401960659650417, \"y\": 0.5395714393028846, \"id\": \"section-curriculum-vitae\", \"label\": \"XVII. Curriculum Vitae\", \"width\": 0.8518791261062123, \"height\": 0.3490479558961003, \"pageNumber\": 2}, {\"x\": 0.07401960659650417, \"y\": 0.888619395198985, \"id\": \"section-signatories\", \"label\": \"Approval Signatories\", \"width\": 0.8518791261062123, \"height\": 0.08822887453258554, \"pageNumber\": 2}, {\"x\": 0.07026143790849673, \"y\": 0.04428178836137821, \"id\": \"section-signatories\", \"label\": \"Approval Signatories\", \"width\": 0.8550653594771241, \"height\": 0.9325664813701924, \"pageNumber\": 3}], \"version\": 1, \"checksum\": \"45e7713307ed4f31d7f8646450c4d2a6c10ae90ff18f3794612577781fe0a67c\"}, \"cooperating_agency\": \"\", \"related_literature\": \"Recent studies associate well-designed interventions in agricultural analytics with measurable efficiency, quality, and satisfaction gains. Adoption depends on usability, trust, accessibility, and the readiness of the people who will use the system.\", \"specific_objectives\": [{\"description\": \"Collect weather, soil, and yield records from partner farms\"}, {\"description\": \"Train and benchmark yield prediction models\"}, {\"description\": \"Pilot advisories with farmers and measure usefulness\"}], \"proponent_department\": \"Department of Computer Science\", \"checked_verified_by_name\": \"Dr. Maria Elena Santos\", \"recommending_approval_name\": \"Dr. Celeste M. Flores\"}', NULL, NULL, NULL, NULL, NULL, '2026-09-27 14:39:37', 1, '2026-09-27 14:39:37', '2026-09-27 14:39:37'),
(203, 32, 'work_plan', 0, '{\"entries\": [{\"months\": [1, 2, 3], \"activity\": \"Collect and clean multi-season farm datasets\", \"objective\": \"Collect weather, soil, and yield records from partner farms\", \"expected_output\": \"Cleaned multi-season farm dataset\"}, {\"months\": [4, 5], \"activity\": \"Train and benchmark prediction models\", \"objective\": \"Train and benchmark yield prediction models\", \"expected_output\": \"Validated yield prediction models\"}, {\"months\": [6, 7], \"activity\": \"Run advisory pilots and analyze farmer feedback\", \"objective\": \"Pilot advisories with farmers and measure usefulness\", \"expected_output\": \"Advisory pilot report with farmer feedback\"}], \"planned_end\": \"2027-04-27\", \"prepared_by\": \"Neil Carlo Delmo\", \"verified_by\": \"Dr. Liza M. Navarro\", \"planned_start\": \"2026-09-28\", \"project_title\": \"Machine Learning Approach to Rice Yield Prediction Using Weather and Soil Data\", \"verified_role\": \"Head, Research and Extension\", \"_revision_sections\": {\"regions\": [{\"x\": 0.03926282051282051, \"y\": 0.16143423840890528, \"id\": \"section-project-information\", \"label\": \"Project Information\", \"width\": 0.9219027777777776, \"height\": 0.15220588235294114, \"pageNumber\": 1}, {\"x\": 0.03926282051282051, \"y\": 0.3136401207618464, \"id\": \"section-schedule\", \"label\": \"Objectives and Gantt Schedule\", \"width\": 0.9219027777777776, \"height\": 0.18995098039215683, \"pageNumber\": 1}, {\"x\": 0.03926282051282051, \"y\": 0.5035911011540033, \"id\": \"section-signatories\", \"label\": \"Signatories\", \"width\": 0.9219027777777776, \"height\": 0.16707883348651958, \"pageNumber\": 1}], \"version\": 1, \"checksum\": \"8ca51be2ae9394eccc5eaf10c748051c1ec98aafb7c5231fa5472cea237b5942\"}, \"total_duration_months\": 7}', NULL, NULL, NULL, NULL, NULL, '2026-09-27 14:39:37', 1, '2026-09-27 14:39:37', '2026-09-27 14:39:37');
