  `action` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'saved',
  `change_note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `change_summary` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
