INSERT INTO `proposal_draft_document_versions` (`id`, `proposal_draft_id`, `topic_id`, `proposal_draft_document_id`, `created_by`, `document_type`, `position`, `version_number`, `is_current`, `action`, `change_note`, `change_summary`, `changes`, `restored_from_version_id`, `source_data`, `file_path`, `original_filename`, `mime_type`, `file_size`, `checksum`, `completed_at`, `created_at`, `updated_at`) VALUES
(1, NULL, 1, NULL, 1, 'detailed_proposal', 0, 1, 0, 'checkpoint', NULL, 'Saved Detailed Research Proposal as a draft.', '[]', NULL, '{\"sdgs\": [4, 9, 16], \"staff\": [], \"rationale\": \"Book collections are difficult to maintain when titles, copies, borrowers, and transactions are recorded in separate or purely manual records. These practices can make it harder to confirm availability, trace borrowing history, and prepare timely reports. This project addresses that operational need by designing a focused system for consistent cataloging, circulation tracking, user access, and reporting.\", \"references\": \"\", \"methodology\": {\"data_analysis\": \"Functional test results will be summarized by passed and failed scenarios. Usability observations and user feedback will be grouped by recurring issue, task clarity, and improvement priority.\", \"research_design\": \"The project will use a developmental research design with an iterative software-development approach. Requirements will be translated into a working prototype, reviewed through representative use cases, and refined based on documented findings.\", \"specific_methods\": \"\"}, \"introduction\": \"Accessible and well-organized book records support efficient learning, information access, and daily library or collection operations. A Book Management System can provide a single source of truth for titles, copies, borrower records, and circulation activity. This proposal presents the development of a focused system that supports reliable recordkeeping, faster transaction lookup, and useful management reports.\", \"leader_email\": \"23-78498@g.batstate-u.edu.ph\", \"leader_title\": \"\", \"project_title\": \"Book Management System\", \"leader_contact\": \"\", \"project_leader\": \"Neil Carlo Delmo\", \"executive_brief\": \"The Book Management System will provide a centralized web-based workspace for recording books, tracking availability, managing borrowers, and producing dependable circulation reports. The project will organize the core book-management activities into one accessible system that can be improved through user feedback and iterative testing.\", \"research_agenda\": \"Digital Transformation, ICT Innovation, and Smart Governance\", \"approved_by_name\": \"\", \"expected_outputs\": {\"patent\": [], \"policy\": [{\"unit\": \"process guide\", \"quantity\": 1, \"description\": \"Documented process guide for maintaining book records and circulation transactions.\"}], \"product\": [{\"unit\": \"system\", \"quantity\": 1, \"description\": \"Functional web-based Book Management System prototype with catalog, borrower, circulation, and reporting modules.\"}], \"publication\": [], \"social_impact\": [{\"unit\": \"assessment\", \"quantity\": 1, \"description\": \"Usability and workflow assessment based on representative users and test scenarios.\"}], \"people_service\": [{\"unit\": \"user guide\", \"quantity\": 1, \"description\": \"User guide and orientation material for authorized staff and borrowers.\"}], \"economic_impact\": [], \"place_partnership\": []}, \"proponent_campus\": \"BatStateU The NEU ARASOF-Nasugbu Campus\", \"responsibilities\": [{\"name\": \"Neil Carlo Delmo\", \"duties\": \"Lead the requirements analysis, system design, development, testing, documentation, and preparation of the project outputs.\", \"percentage\": 100}], \"general_objective\": \"To design and develop a web-based Book Management System that improves the organization, circulation, and monitoring of book records.\", \"proponent_college\": \"\", \"cooperating_agency\": \"\", \"methodology_images\": [], \"related_literature\": \"\", \"specific_objectives\": [{\"description\": \"Identify the functional and information requirements for cataloging books, managing borrowers, and recording circulation transactions.\"}, {\"description\": \"Design a clear data structure and user workflow for book records, copies, borrowers, borrowing, returns, and availability status.\"}, {\"description\": \"Develop and integrate the core Book Management System modules with role-appropriate access and validation.\"}, {\"description\": \"Test the system functions and usability using representative book and circulation scenarios, then document recommended improvements.\"}], \"literature_citations\": \"[]\", \"proponent_department\": \"\", \"checked_verified_by_name\": \"\", \"recommending_approval_name\": \"\", \"specific_method_objectives\": [{\"heading\": \"Requirements and system design\", \"methods\": [{\"description\": \"Review the current book-record and circulation workflow with intended users.\"}, {\"description\": \"Define the data fields, user roles, validation rules, and process flow for the system.\"}, {\"description\": \"Prepare the initial interface and database design for review.\"}]}, {\"heading\": \"Development and integration\", \"methods\": [{\"description\": \"Implement the catalog, borrower, circulation, availability, and reporting features.\"}, {\"description\": \"Connect the modules and apply access controls, validation, and record-history safeguards.\"}, {\"description\": \"Prepare representative records and scenarios for functional testing.\"}]}, {\"heading\": \"Testing and evaluation\", \"methods\": [{\"description\": \"Run functional tests for common cataloging, borrowing, return, and reporting tasks.\"}, {\"description\": \"Observe representative users completing selected workflows and record usability findings.\"}, {\"description\": \"Prioritize corrections and document the recommended next iteration.\"}]}], \"literature_research_history\": \"[]\"}', NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-16 09:03:39', '2026-08-20 01:23:05'),
