  `volume` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `issue` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pages` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
