INSERT INTO `proposal_version_files` (`id`, `proposal_version_id`, `source_version_file_id`, `document_type`, `position`, `file_path`, `original_filename`, `mime_type`, `file_size`, `checksum`, `source_data`, `is_carried_forward`, `uploaded_by`, `superseded_at`, `superseded_by_version_file_id`, `created_at`, `updated_at`) VALUES
(1, 1, NULL, 'detailed_proposal', 0, 'proposal-packages/1/c5fe1101-201a-4d74-aae6-be54ac18741f/detailed-proposal/b577a0a7-0416-400c-9745-60e726a2e0f2.pdf', 'book-management-system-detailed-research-proposal.pdf', 'application/pdf', 261084, '5e91d51a45f6ee5a8e5c5979e24971fd8a4e41bfc50eadd2a731a47a0ca08abe', '{\"sdgs\": [\"4\", \"9\", \"16\"], \"staff\": null, \"rationale\": \"<p>Book collections are difficult to maintain when titles, copies, borrowers, and transactions are recorded in separate or purely manual records. These practices can make it harder to confirm availability, trace borrowing history, and prepare timely reports. This project addresses that operational need by designing a focused system for consistent cataloging, circulation tracking, user access, and reporting.</p>\", \"references\": \"[1] I. Sommerville, Software Engineering, 10th ed. Pearson, 2016.\\n[2] R. S. Pressman and B. R. Maxim, Software Engineering: A Practitioners Approach, 9th ed. McGraw-Hill Education, 2019.\", \"methodology\": {\"data_analysis\": \"<p>Functional test results will be summarized by passed and failed scenarios. Usability observations and user feedback will be grouped by recurring issue, task clarity, and improvement priority.</p>\", \"research_design\": \"<p>The project will use a developmental research design with an iterative software-development approach. Requirements will be translated into a working prototype, reviewed through representative use cases, and refined based on documented findings.</p>\", \"specific_methods\": \"<p><strong>A. Requirements and system design</strong></p><ol><li>Review the current book-record and circulation workflow with intended users.</li><li>Define the data fields, user roles, validation rules, and process flow for the system.</li><li>Prepare the initial interface and database design for review.</li></ol><p><strong>B. Development and integration</strong></p><ol><li>Implement the catalog, borrower, circulation, availability, and reporting features.</li><li>Connect the modules and apply access controls, validation, and record-history safeguards.</li><li>Prepare representative records and scenarios for functional testing.</li></ol><p><strong>C. Testing and evaluation</strong></p><ol><li>Run functional tests for common cataloging, borrowing, return, and reporting tasks.</li><li>Observe representative users completing selected workflows and record usability findings.</li><li>Prioritize corrections and document the recommended next iteration.</li></ol>\"}, \"introduction\": \"<p>Accessible and well-organized book records support efficient learning, information access, and daily library or collection operations. A Book Management System can provide a single source of truth for titles, copies, borrower records, and circulation activity. This proposal presents the development of a focused system that supports reliable recordkeeping, faster transaction lookup, and useful management reports.</p>\", \"leader_email\": \"23-78498@g.batstate-u.edu.ph\", \"leader_title\": null, \"project_title\": \"Book Management System\", \"leader_contact\": \"09170000001\", \"project_leader\": \"Neil Carlo Delmo\", \"executive_brief\": \"<p>The Book Management System will provide a centralized web-based workspace for recording books, tracking availability, managing borrowers, and producing dependable circulation reports. The project will organize the core book-management activities into one accessible system that can be improved through user feedback and iterative testing.</p>\", \"research_agenda\": \"Digital Transformation, ICT Innovation, and Smart Governance\", \"approved_by_name\": null, \"expected_outputs\": {\"patent\": [], \"policy\": [{\"unit\": \"\", \"quantity\": null, \"description\": \"One (1) process guide Documented process guide for maintaining book records and circulation transactions.\"}], \"product\": [{\"unit\": \"\", \"quantity\": null, \"description\": \"One (1) system Functional web-based Book Management System prototype with catalog, borrower, circulation, and reporting modules.\"}], \"publication\": [], \"social_impact\": [{\"unit\": \"\", \"quantity\": null, \"description\": \"One (1) assessment Usability and workflow assessment based on representative users and test scenarios.\"}], \"people_service\": [{\"unit\": \"\", \"quantity\": null, \"description\": \"One (1) user guide User guide and orientation material for authorized staff and borrowers.\"}], \"economic_impact\": [], \"place_partnership\": []}, \"proponent_campus\": \"BatStateU The NEU ARASOF-Nasugbu Campus\", \"responsibilities\": [{\"name\": \"Neil Carlo Delmo\", \"duties\": \"<p>Lead the requirements analysis, system design, development, testing, documentation, and preparation of the project outputs.</p>\", \"percentage\": \"100\"}], \"general_objective\": \"<p>To design and develop a web-based Book Management System that improves the organization, circulation, and monitoring of book records.</p>\", \"proponent_college\": \"College of Informatics and Computing Sciences\", \"cooperating_agency\": null, \"methodology_images\": [], \"related_literature\": \"Software engineering literature emphasizes requirements analysis, iterative development, validation, and user-centered evaluation as foundations for reliable information systems. These principles support the proposed Book Management System by guiding the conversion of book-circulation workflows into validated modules and tested user tasks. The project will apply these concepts while tailoring the implementation to the intended book-record environment.\", \"specific_objectives\": [{\"description\": \"Identify the functional and information requirements for cataloging books, managing borrowers, and recording circulation transactions.\"}, {\"description\": \"Design a clear data structure and user workflow for book records, copies, borrowers, borrowing, returns, and availability status.\"}, {\"description\": \"Develop and integrate the core Book Management System modules with role-appropriate access and validation.\"}, {\"description\": \"Test the system functions and usability using representative book and circulation scenarios, then document recommended improvements.\"}], \"literature_citations\": \"[]\", \"proponent_department\": \"\", \"checked_verified_by_name\": null, \"recommending_approval_name\": null, \"specific_method_objectives\": [{\"heading\": \"Requirements and system design\", \"methods\": [{\"description\": \"Review the current book-record and circulation workflow with intended users.\"}, {\"description\": \"Define the data fields, user roles, validation rules, and process flow for the system.\"}, {\"description\": \"Prepare the initial interface and database design for review.\"}]}, {\"heading\": \"Development and integration\", \"methods\": [{\"description\": \"Implement the catalog, borrower, circulation, availability, and reporting features.\"}, {\"description\": \"Connect the modules and apply access controls, validation, and record-history safeguards.\"}, {\"description\": \"Prepare representative records and scenarios for functional testing.\"}]}, {\"heading\": \"Testing and evaluation\", \"methods\": [{\"description\": \"Run functional tests for common cataloging, borrowing, return, and reporting tasks.\"}, {\"description\": \"Observe representative users completing selected workflows and record usability findings.\"}, {\"description\": \"Prioritize corrections and document the recommended next iteration.\"}]}], \"literature_research_history\": \"[{\\\"id\\\":\\\"Book Management System improves organization circulation monitoring records Identify functional information requirements cataloging books managing borrowers-1786871429978\\\",\\\"query\\\":\\\"Book Management System improves organization circulation monitoring records Identify functional information requirements cataloging books managing borrowers\\\",\\\"label\\\":\\\"Book Management System\\\",\\\"context\\\":[\\\"Project title\\\",\\\"General objective\\\",\\\"Specific objectives\\\"],\\\"resultCount\\\":12,\\\"searchedAt\\\":\\\"2026-08-16T09:10:29.979Z\\\"}]\"}', 0, NULL, NULL, NULL, '2026-08-20 01:23:05', '2026-08-20 01:23:05'),
(2, 1, NULL, 'work_plan', 0, 'proposal-packages/1/c5fe1101-201a-4d74-aae6-be54ac18741f/work-plan/52953bab-8357-46fd-9856-047768acb26c.pdf', 'book-management-system-work-plan.pdf', 'application/pdf', 137228, '758e05b1957ff2ae869ea2997f40d49902b1600066c887e946cab19b99ea412b', '{\"entries\": [{\"months\": [1, 2, 3], \"activity\": \"Interview library staff, review current borrowing and cataloging procedures, and document the required book catalog, search, and circulation features.\", \"objective\": \"Analyze library workflows and define requirements for the Book Management System.\", \"expected_output\": \"Validated requirements specification and workflow map.\"}], \"planned_end\": \"2027-08-31\", \"prepared_by\": \"Neil Carlo Delmo\", \"planned_start\": \"2026-09-01\", \"project_title\": \"Book Management System\", \"total_duration_months\": 12}', 0, NULL, NULL, NULL, '2026-08-20 01:23:05', '2026-08-20 01:23:05'),
