(50, 7, NULL, 'work_plan', 0, 'proposal-packages/lifecycle-demo/7/v1/work_plan-0.pdf', 'development-of-a-digital-barangay-services-and-citizen-request-management-system-work-plan.pdf', 'application/pdf', 154056, '83cc6735a2104b06b232aa64841af794a95585ab608c54f81963bd4f83882948', '{\"entries\": [{\"months\": [1, 2, 3], \"activity\": \"Conduct interviews, observations, and process mapping\", \"objective\": \"Document current service workflows\", \"expected_output\": \"Validated process and requirements report\"}, {\"months\": [4, 5, 6], \"activity\": \"Design, implement, and internally test system modules\", \"objective\": \"Develop the digital service platform\", \"expected_output\": \"Testable role-based web application\"}, {\"months\": [7, 8, 9], \"activity\": \"Run pilot tests, analyze results, and finalize recommendations\", \"objective\": \"Evaluate the pilot implementation\", \"expected_output\": \"Usability, performance, and acceptance report\"}], \"planned_end\": \"2027-06-09\", \"prepared_by\": \"Neil Carlo Delmo\", \"verified_by\": \"Dr. Liza M. Navarro\", \"planned_start\": \"2026-09-09\", \"project_title\": \"Development of a Digital Barangay Services and Citizen Request Management System\", \"verified_role\": \"Head, Research and Extension\", \"_revision_sections\": {\"regions\": [{\"x\": 0.03926282051282051, \"y\": 0.16143423840890528, \"id\": \"section-project-information\", \"label\": \"Project Information\", \"width\": 0.9219027777777776, \"height\": 0.15220588235294114, \"pageNumber\": 1}, {\"x\": 0.03926282051282051, \"y\": 0.3136401207618464, \"id\": \"section-schedule\", \"label\": \"Objectives and Gantt Schedule\", \"width\": 0.9219027777777776, \"height\": 0.21299019607843145, \"pageNumber\": 1}, {\"x\": 0.03926282051282051, \"y\": 0.5266303168402778, \"id\": \"section-signatories\", \"label\": \"Signatories\", \"width\": 0.9219027777777776, \"height\": 0.16707883348651958, \"pageNumber\": 1}], \"version\": 1, \"checksum\": \"83cc6735a2104b06b2