(169, 24, 162, 'work_plan', 0, 'proposal-packages/lifecycle-demo/17/v1/work_plan-0.pdf', 'computer-vision-system-for-automated-attendance-in-large-lecture-classes-work-plan.pdf', 'application/pdf', 153507, '0b223faa76cb21e7ab8d1864f953fb92e6441575a6962b654381aacdbbfaa952', '{\"entries\": [{\"months\": [1, 2, 3], \"activity\": \"Collect consented classroom image datasets\", \"objective\": \"Benchmark recognition accuracy in high-density classrooms\", \"expected_output\": \"Consented classroom benchmark dataset\"}, {\"months\": [4, 5, 6], \"activity\": \"Train and optimize recognition models\", \"objective\": \"Integrate recognition with enrollment records\", \"expected_output\": \"Attendance recognition service\"}, {\"months\": [7, 8], \"activity\": \"Run parallel manual and automated attendance trials\", \"objective\": \"Evaluate accuracy, throughput, and privacy acceptance\", \"expected_output\": \"Accuracy and privacy acceptance report\"}], \"planned_end\": \"2027-06-21\", \"prepared_by\": \"Neil Carlo Delmo\", \"verified_by\": \"Dr. Liza M. Navarro\", \"planned_start\": \"2026-10-22\", \"project_title\": \"Computer Vision System for Automated Attendance in Large Lecture Classes\", \"verified_role\": \"Head, Research and Extension\", \"_revision_sections\": {\"regions\": [{\"x\": 0.03926282051282051, \"y\": 0.16143423840890528, \"id\": \"section-project-information\", \"label\": \"Project Information\", \"width\": 0.9219027777777776, \"height\": 0.15220588235294114, \"pageNumber\": 1}, {\"x\": 0.03926282051282051, \"y\": 0.3136401207618464, \"id\": \"section-schedule\", \"label\": \"Objectives and Gantt Schedule\", \"width\": 0.9219027777777776, \"height\": 0.18995098039215683, \"pageNumber\": 1}, {\"x\": 0.03926282051282051, \"y\": 0.5035911011540033, \"id\": \"section-signatories\", \"label\": \"Signatories\", \"width\": 0.9219027777777776, \"height\": 0.16707883348651958, \"pageNumber\": 1}], \"version\": 1, \"checksum\": \"0b223faa76cb21e7ab8d1864f953fb92e6441