INSERT INTO `proposal_version_files` (`id`, `proposal_version_id`, `source_version_file_id`, `document_type`, `position`, `file_path`, `original_filename`, `mime_type`, `file_size`, `checksum`, `source_data`, `is_carried_forward`, `uploaded_by`, `superseded_at`, `superseded_by_version_file_id`, `created_at`, `updated_at`) VALUES
(269, 39, NULL, 'detailed_proposal', 0, 'proposal-packages/lifecycle-demo/26/v1/detailed_proposal-0.pdf', 'gamified-disaster-preparedness-training-for-coastal-communities-detailed-research-proposal.pdf', 'application/pdf', 247262, 'ff8ad4ceffbabb415a95c16ffd20f610a914e72436d24b3bf4770e1b9ea46bce', '{\"sdgs\": [4, 11, 13], \"staff\": [], \"rationale\": \"Current practice in community resilience education still depends on manual processes and fragmented records. This leads to slow turnaround, limited visibility, and inconsistent reporting. A structured and technology-enabled approach can shorten processing time, strengthen traceability, and make outcomes easier to measure while keeping stakeholders in control of decisions.\", \"references\": \"Marasigan, O. (2024). Game-based learning for disaster risk reduction. International Journal of Disaster Risk Reduction, 13(2), 60-77. Santos, M. (2025). Applied research methods for community-centered technology. Philippine Journal of Science, 154(2), 101-115.\", \"methodology\": {\"data_analysis\": \"Quantitative results will be summarized using descriptive statistics, while qualitative feedback will undergo thematic analysis.\", \"research_design\": \"The study will use a developmental research design with mixed-method evaluation.\", \"specific_methods\": \"Researchers will review existing workflows, co-design the solution with stakeholders, implement it iteratively, and evaluate it through controlled pilot testing.\"}, \"introduction\": \"The project Gamified Disaster Preparedness Training for Coastal Communities responds to persistent gaps in community resilience education, where fragmented processes limit reliability and responsiveness. This study designs and evaluates a practical solution grounded in the day-to-day needs of its intended users.\", \"leader_email\": \"23-73453@g.batstate-u.edu.ph\", \"leader_title\": \"Mr.\", \"project_title\": \"Gamified Disaster Preparedness Training for Coastal Communities\", \"leader_contact\": \"09170000009\", \"project_leader\": \"Djanisse Villaflor\", \"executive_brief\": \"This project will design, build, and evaluate a gamified preparedness training kit for coastal barangays to improve how community resilience education is carried out in partner communities and campus units.\", \"research_agenda\": \"Environment, Climate Change, and Climate Resilience\", \"approved_by_name\": \"Dr. Patricia Anne Villanueva\", \"expected_outputs\": {\"patent\": [], \"policy\": [{\"description\": \"An adoption guide for university and community stakeholders\"}], \"product\": [{\"description\": \"A gamified preparedness training kit for coastal barangays\"}], \"publication\": [{\"description\": \"One peer-reviewed research article\"}], \"social_impact\": [{\"description\": \"Improved access to timely and reliable services for the target community\"}], \"people_service\": [{\"description\": \"A validated usability and acceptance report from pilot participants\"}], \"economic_impact\": [{\"description\": \"More efficient use of institutional and community resources\"}], \"place_partnership\": [{\"description\": \"A working partnership between the university and participating community sites\"}]}, \"proponent_campus\": \"Alangilan Campus\", \"responsibilities\": [{\"name\": \"Djanisse Villaflor\", \"duties\": \"Leads project planning, implementation, quality assurance, data analysis, and reporting.\", \"percentage\": 100}], \"general_objective\": \"Develop and evaluate a gamified preparedness training kit for coastal barangays.\", \"proponent_college\": \"College of Informatics and Computing Sciences\", \"_revision_sections\": {\"regions\": [{\"x\": 0.07401960659650417, \"y\": 0.11314105172442576, \"id\": \"section-project-information\", \"label\": \"I. Research Project Title\", \"width\": 0.8518791261062123, \"height\": 0.028846153846153848, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.1419872055705796, \"id\": \"section-research-agenda\", \"label\": \"II. Research Agenda\", \"width\": 0.8518791261062123, \"height\": 0.02425208458533654, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.16623929015591613, \"id\": \"section-sdgs\", \"label\": \"III. Sustainable Development Goal\", \"width\": 0.8518791261062123, \"height\": 0.16837610750116855, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.33461539765708465, \"id\": \"section-project-team\", \"label\": \"IV. Project Leader and Staff\", \"width\": 0.8518791261062123, \"height\": 0.09391021728515624, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.4285256149422409, \"id\": \"section-proponent\", \"label\": \"V. Proponent Agency\", \"width\": 0.8518791261062123, \"height\": 0.0623931884765625, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.4909188034188034, \"id\": \"section-cooperating-agency\", \"label\": \"VI. Cooperating Agency\", \"width\": 0.8518791261062123, \"height\": 0.023183773725460734, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.5141025771442641, \"id\": \"section-executive-brief\", \"label\": \"VII. Executive Brief\", \"width\": 0.8518791261062123, \"height\": 0.04946579892411191, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.5635683760683761, \"id\": \"section-rationale\", \"label\": \"VIII. Rationale\", \"width\": 0.8518791261062123, \"height\": 0.07767095321264023, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.6412393292810163, \"id\": \"section-objectives\", \"label\": \"IX. Objectives of the Project\", \"width\": 0.8518791261062123, \"height\": 0.15085468129215077, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.7920940105731671, \"id\": \"section-expected-outputs\", \"label\": \"X. Expected Output of the Project\", \"width\": 0.8518791261062123, \"height\": 0.1278846202752529, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.91997863084842, \"id\": \"section-literature\", \"label\": \"XI. Introduction and Related Literature\", \"width\": 0.8518791261062123, \"height\": 0.05686963888315057, \"pageNumber\": 1}, {\"x\": 0.07401960659650417, \"y\": 0.04428178836137821, \"id\": \"section-literature\", \"label\": \"XI. Introduction and Related Literature\", \"width\": 0.8518791261062123, \"height\": 0.12676519410223022, \"pageNumber\": 2}, {\"x\": 0.07401960659650417, \"y\": 0.17104698246360844, \"id\": \"section-methodology\", \"label\": \"XII. Methodology\", \"width\": 0.8518791261062123, \"height\": 0.14722227438902244, \"pageNumber\": 2}, {\"x\": 0.07401960659650417, \"y\": 0.31826925685263086, \"id\": \"section-responsibilities\", \"label\": \"XIII. Duties and Responsibilities\", \"width\": 0.8518791261062123, \"height\": 0.06217943501268697, \"pageNumber\": 2}, {\"x\": 0.07401960659650417, \"y\": 0.3804486918653178, \"id\": \"section-work-plan\", \"label\": \"XIV. Major Activities / Work Plan\", \"width\": 0.8518791261062123, \"height\": 0.023183773725460734, \"pageNumber\": 2}, {\"x\": 0.07401960659650417, \"y\": 0.4036324655907786, \"id\": \"section-budget\", \"label\": \"XV. Line-Item Budget\", \"width\": 0.8518791261062123, \"height\": 0.06816000653128336, \"pageNumber\": 2}, {\"x\": 0.07401960659650417, \"y\": 0.47179247212206193, \"id\": \"section-references\", \"label\": \"XVI. References\", \"width\": 0.8518791261062123, \"height\": 0.06777896718082273, \"pageNumber\": 2}, {\"x\": 0.07401960659650417, \"y\": 0.5395714393028846, \"id\": \"section-curriculum-vitae\", \"label\": \"XVII. Curriculum Vitae\", \"width\": 0.8518791261062123, \"height\": 0.3490479558961003, \"pageNumber\": 2}, {\"x\": 0.07401960659650417, \"y\": 0.888619395198985, \"id\": \"section-signatories\", \"label\": \"Approval Signatories\", \"width\": 0.8518791261062123, \"height\": 0.08822887453258554, \"pageNumber\": 2}, {\"x\": 0.07026143790849673, \"y\": 0.04428178836137821, \"id\": \"section-signatories\", \"label\": \"Approval Signatories\", \"width\": 0.8550653594771241, \"height\": 0.9325664813701924, \"pageNumber\": 3}], \"version\": 1, \"checksum\": \"ff8ad4ceffbabb415a95c16ffd20f610a914e72436d24b3bf4770e1b9ea46bce\"}, \"cooperating_agency\": \"\", \"related_literature\": \"Recent studies associate well-designed interventions in community resilience education with measurable efficiency, quality, and satisfaction gains. Adoption depends on usability, trust, accessibility, and the readiness of the people who will use the system.\", \"specific_objectives\": [{\"description\": \"Baseline community preparedness knowledge\"}, {\"description\": \"Develop the gamified training kit\"}, {\"description\": \"Measure preparedness knowledge retention\"}], \"proponent_department\": \"Department of Information Technology\", \"checked_verified_by_name\": \"Dr. Maria Elena Santos\", \"recommending_approval_name\": \"Dr. Celeste M. Flores\"}', 0, 2, NULL, NULL, '2026-09-13 02:45:50', '2026-09-13 02:45:50'),
